#include "BackupManager.h"
#include "App/AppPaths.h"
namespace vox {juce::File BackupManager::directory()const{auto d=AppPaths::data().getChildFile("Backups");d.createDirectory();return d;}juce::File BackupManager::create(const juce::String&description)const{auto out=directory().getChildFile("Backup-"+juce::Time::getCurrentTime().formatted("%Y%m%d-%H%M%S"));out.createDirectory();auto data=AppPaths::data();for(auto name:{"settings.json","preferences.json","favorites.json"}){auto f=data.getChildFile(name);if(f.existsAsFile())f.copyFileTo(out.getChildFile(name));}auto users=data.getChildFile("Admin").getChildFile("users.json");if(users.existsAsFile())users.copyFileTo(out.getChildFile("users.json"));out.getChildFile("manifest.txt").replaceWithText("Version=1.0.0\nCreated="+juce::Time::getCurrentTime().toISO8601(true)+"\nDescription="+description);return out;}juce::Array<juce::File>BackupManager::list()const{return directory().findChildFiles(juce::File::findDirectories,false,"Backup-*");}bool BackupManager::remove(const juce::File&f)const{return f.isAChildOf(directory())&&f.deleteRecursively();}}
